mapper.select:
select t.task_id, t.instance_id, t.node_id, t.node_name, t.assignee, t.assignee_name,
       t.status, t.comment, t.approve_time, t.create_time,
       i.flow_name, i.biz_type, i.biz_id, i.biz_code, i.biz_name, i.status instance_status,
       i.submit_by, i.submit_name, i.submit_time
from pm_flow_task t
join pm_flow_instance i on i.instance_id = t.instance_id

    and t.assignee = #{assignee}
    and t.instance_id = #{instanceId}
    and t.status = #{status}

order by t.task_id desc

mapper.update:
update pm_flow_task
set status = #{status}, comment = #{comment}, approve_time = #{approveTime}, update_time = sysdate()
where task_id = #{taskId}
